def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    out = [row[:] for row in grid]

    def mask(box, color, flip_r, flip_c):
        r0, r1, c0, c1 = box
        return {
            (r1 - 1 - r if flip_r else r - r0,
             c1 - 1 - c if flip_c else c - c0)
            for r in range(r0, r1)
            for c in range(c0, c1)
            if grid[r][c] == color
        }

    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            r0, r1 = rows[i]
            r2, r3 = rows[i + 1]
            c0, c1 = cols[j]
            c2, c3 = cols[j + 1]
            if (r1 - r0 != r3 - r2 or c1 - c0 != c3 - c2):
                continue

            boxes = [
                (r0, r1, c0, c1), (r0, r1, c2, c3),
                (r2, r3, c0, c1), (r2, r3, c2, c3)
            ]
            for color in range(1, 10):
                present = [
                    any(grid[r][c] == color
                        for r in range(box[0], box[1])
                        for c in range(box[2], box[3]))
                    for box in boxes
                ]
                if sum(present) != 3:
                    continue

                canonical = [
                    mask(boxes[k], color, k >= 2, k % 2 == 1)
                    for k in range(4) if present[k]
                ]
                if not canonical or any(m != canonical[0] for m in canonical[1:]):
                    continue

                missing = present.index(False)
                box = boxes[missing]
                a, b, x, y = box
                flip_r, flip_c = missing >= 2, missing % 2 == 1
                for rr, cc in canonical[0]:
                    r = b - 1 - rr if flip_r else a + rr
                    c = y - 1 - cc if flip_c else x + cc
                    if out[r][c] == 0:
                        out[r][c] = color

    return out
